export interface BlogPost {
  id: string;
  slug: string;
  title: string;
  description: string;
  image: string;
  date: string;
  tags: string[];
  content: ContentBlock[];
}

export interface ContentBlock {
  type: "text" | "heading" | "quote" | "preface" | "component";
  text: string;
  level?: number;
  componentId?: string;
}

function parseContent(raw: string): ContentBlock[] {
  try {
    const arr = JSON.parse(raw);
    return arr
      .filter((b: any) => ["text", "heading", "quote", "preface"].includes(b.ty))
      .map((b: any) => ({
        type: b.ty === "preface" ? "preface" : b.ty === "heading" ? "heading" : b.ty === "quote" ? "quote" : "text",
        text: b.te || "",
        ...(b.le ? { level: b.le } : {}),
      }));
  } catch {
    return [{ type: "text", text: raw }];
  }
}

function extractImage(media: string): string {
  if (media.startsWith("{")) {
    try {
      return JSON.parse(media).img;
    } catch {
      return media;
    }
  }
  return media;
}

